  accessedAt: string;
  sources: { title: string; url: string; publisher: string; publicationDate: string; accessedAt: string; sourceRole: "company_primary" | "organization_primary" | "creator_primary" | "platform_primary" | "independent_secondary"; claimRole: "action" | "outcome" | "action_and_outcome" | "context"; supports: string }[];
